function findSeed(obs) {
  const r1Min = ((obs.pos.x + 2.1 - 0.0015 + 0.045) / 0.09) * 4294967296;
  const r1Max = ((obs.pos.x + 2.1 + 0.0015 + 0.045) / 0.09) * 4294967296;
  const r2Min = ((obs.pos.z + 1.65 - 0.0015 + 0.045) / 0.09) * 4294967296;
  const r2Max = ((obs.pos.z + 1.65 + 0.0015 + 0.045) / 0.09) * 4294967296;
  for (let s = 0; s < 2000000; s++) {
    let a = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const u1 = (t ^ (t >>> 14)) >>> 0;
    if (u1 < r1Min || u1 > r1Max) continue;
    a = (a + 0x6d2b79f5) >>> 0;
    t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const u2 = (t ^ (t >>> 14)) >>> 0;
    if (u2 < r2Min || u2 > r2Max) continue;
    // Check rng for pos.y
    let b = (s ^ 0xa5a5a5a5) >>> 0;
    const nextB = () => {
      b = (b + 0x6d2b79f5) >>> 0;
      let tb = Math.imul(b ^ (b >>> 15), b | 1);
      tb ^= tb + Math.imul(tb ^ (tb >>> 7), tb | 61);
      return ((tb ^ (tb >>> 14)) >>> 0) / 4294967296;
    };
    nextB(); nextB(); nextB(); // pos.x
    const py = 0.07 + (nextB() + nextB() + nextB() - 1.5) * 0.001;
    if (py === obs.pos.y) return s;
  }
