import("./tasks/drone/task.mjs").then(async ({ TASK, trialParameters, random }) => {
  const { initialState } = await import("./tasks/drone/sim.mjs");
  const MOTOR_X = [-1, 1, 1, -1], MOTOR_Z = [-1, -1, 1, 1], SPIN = [1, -1, 1, -1];
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  function stepRotY(s, action, params, dt) {
    const { att, rates } = s;
    const inertia = TASK.inertia * params.mass / TASK.baseMass;
    const torque = {};
    for (const axis of ["roll", "pitch"]) {
      const error = action[axis] - att[axis];
      s.integral[axis] = clamp(s.integral[axis] + error * dt, -0.35, 0.35);
      torque[axis] = inertia * (65 * error - 13 * rates[axis] + 22 * s.integral[axis]);
    }
    torque.yaw = inertia * 8 * (action.yawRate - rates.yaw);
    for (let i = 0; i < 4; i++) {
      const desired = action.thrust * TASK.maxMotorThrust +
        torque.roll * MOTOR_Z[i] / (4 * TASK.arm) - torque.pitch * MOTOR_X[i] / (4 * TASK.arm) +
        torque.yaw * SPIN[i] / (4 * TASK.yawCoefficient);
      const target = clamp(desired, 0, TASK.maxMotorThrust) * (i === params.weakMotor ? 1 - params.weakness : 1);
      s.motors[i] += (target - s.motors[i]) * (1 - Math.exp(-dt / params.lag));
    }
    const sum = s.motors[0] + s.motors[1] + s.motors[2] + s.motors[3];
    let mZ = 0, mX = 0, mS = 0;
    for (let i = 0; i < 4; i++) {
      mZ += s.motors[i] * MOTOR_Z[i];
      mX += s.motors[i] * MOTOR_X[i];
      mS += s.motors[i] * SPIN[i];
    }
    rates.roll += (TASK.arm * mZ / inertia - 0.4 * rates.roll) * dt;
    rates.pitch += (-TASK.arm * mX / inertia - 0.4 * rates.pitch) * dt;
    rates.yaw += (TASK.yawCoefficient * mS / inertia - 0.4 * rates.yaw) * dt;
    att.roll += rates.roll * dt;
    att.pitch += rates.pitch * dt;
    att.yaw += rates.yaw * dt;
    const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
    const forceY = sum * dirY - TASK.linearDrag * s.vy;
    s.vy += (forceY / params.mass - TASK.gravity) * dt;
    s.py += s.vy * dt;
    if (s.py <= TASK.bodyHeight) {
      s.py = TASK.bodyHeight;
      s.vy = Math.max(0, s.vy);
    }
  }

  // Test identification on seed 101 after 60 steps (0.6s)
  const seed = 101;
  const trueParams = trialParameters(seed);
  const rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
  const sTrue = { att: {roll:0, pitch:0, yaw:0}, rates: {roll:0, pitch:0, yaw:0}, motors: [0,0,0,0], integral: {roll:0, pitch:0}, py: TASK.bodyHeight, vy: 0 };
  const history = [];
  for (let k = 0; k < 60; k++) {
    const obs = {
      py: sTrue.py + noise(TASK.positionNoise),
      vy: sTrue.vy + noise(TASK.velocityNoise),
      att: { roll: sTrue.att.roll + noise(TASK.attitudeNoise), pitch: sTrue.att.pitch + noise(TASK.attitudeNoise), yaw: sTrue.att.yaw + noise(TASK.attitudeNoise) },
      rates: { roll: sTrue.rates.roll + noise(TASK.rateNoise), pitch: sTrue.rates.pitch + noise(TASK.rateNoise), yaw: sTrue.rates.yaw + noise(TASK.rateNoise) },
    };
    const action = { thrust: 0.65, roll: 0.1 * Math.sin(k * 0.1), pitch: 0.1 * Math.cos(k * 0.1), yawRate: 0 };
    history.push({ obs, action });
    stepRotY(sTrue, action, trueParams, 0.005);
    stepRotY(sTrue, action, trueParams, 0.005);
  }

  function loss(params) {
    const s = { att: {roll:0, pitch:0, yaw:0}, rates: {roll:0, pitch:0, yaw:0}, motors: [0,0,0,0], integral: {roll:0, pitch:0}, py: TASK.bodyHeight, vy: 0 };
    let err = 0;
    for (let k = 0; k < history.length; k++) {
      const { obs, action } = history[k];
      const dy = s.py - obs.py, dvy = s.vy - obs.vy;
      const dr = s.att.roll - obs.att.roll, dp = s.att.pitch - obs.att.pitch, dyaw = s.att.yaw - obs.att.yaw;
      const drr = s.rates.roll - obs.rates.roll, drp = s.rates.pitch - obs.rates.pitch, dry = s.rates.yaw - obs.rates.yaw;
      err += 1e6 * dy * dy + 3e3 * dvy * dvy + 1e5 * (dr * dr + dp * dp + dyaw * dyaw) + 5e3 * (drr * drr + drp * drp + dry * dry);
      stepRotY(s, action, params, 0.005);
      stepRotY(s, action, params, 0.005);
    }
    return err;
  }

  const t0 = performance.now();
  // Determine weakMotor from initial yaw/roll/pitch rate signs or grid search
  let best = null, bestLoss = Infinity;
  for (let wm = 0; wm < 4; wm++) {
    for (const mass of [0.65, 0.75, 0.82]) {
      for (const lag of [0.028, 0.045]) {
        for (const weakness of [0.03, 0.12, 0.22]) {
          const p = { weakMotor: wm, mass, lag, weakness };
          const l = loss(p);
          if (l < bestLoss) { bestLoss = l; best = p; }
        }
      }
    }
  }
  // Coordinate descent refinement
  let steps = { mass: 0.04, lag: 0.008, weakness: 0.04 };
  for (let iter = 0; iter < 18; iter++) {
    for (const [k, lo, hi] of [["mass", 0.6, 0.85], ["weakness", 0, 0.25], ["lag", 0.02, 0.06]]) {
      const orig = best[k];
      for (const dir of [-1, 1]) {
        best[k] = clamp(orig + dir * steps[k], lo, hi);
        const l = loss(best);
        if (l < bestLoss) { bestLoss = l; break; }
        best[k] = orig;
      }
    }
    steps.mass *= 0.65; steps.lag *= 0.65; steps.weakness *= 0.65;
  }
  const t1 = performance.now();
  console.log("True:", { weakMotor: trueParams.weakMotor, mass: trueParams.mass, lag: trueParams.lag, weakness: trueParams.weakness });
  console.log("Est :", best, "in", (t1 - t0).toFixed(2), "ms");
});
