export default function makeController() {
  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;

  let px = null, py = 0.07, pz = null;
  let vx = 0, vy = 0, vz = 0;
  let wx = 0, wz = 0;
  let wBaseX = 0, wBaseZ = 0, baseCount = 0;

  let KT = 21.0, estMass = 0.72;
  let uT = 0.48;
  let lastThrust = 0.48, lastRollDes = 0, lastPitchDes = 0;
  let prevDirX = 0, prevDirY = 1, prevDirZ = 0;
  let refRoll = 0, refPitch = 0;
  let trimRoll = 0, trimPitch = 0;
  let intYaw = 0, intY = 0, intX = 0, intZ = 0;

  const histVx = [0, 0, 0, 0], histVz = [0, 0, 0, 0];
  const histAx = [0, 0, 0, 0], histAz = [0, 0, 0, 0];
  let stepCount = 0;

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dt = 0.01;

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);

      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (px === null) {
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        prevDirX = dirX; prevDirY = dirY; prevDirZ = dirZ;
      } else {
        uT += (lastThrust - uT) * (1 - Math.exp(-dt / 0.04));
        const avgDirX = 0.5 * (prevDirX + dirX);
        const avgDirY = 0.5 * (prevDirY + dirY);
        const avgDirZ = 0.5 * (prevDirZ + dirZ);
        const cDrag = 0.42 / estMass;

        const ayPred = KT * uT * avgDirY - cDrag * vy - 9.81;
        const vyPred = vy + ayPred * dt;
        const pyPred = Math.max(0.07, py + vyPred * dt);
        const epY = p.y - pyPred;
        const evY = v.y - vyPred;
        py = pyPred + 0.65 * epY + 0.002 * evY;
        vy = vyPred + 8.0 * epY + 0.40 * evY;

        if (p.y > 0.11 && p.y < 2.85 && uT * avgDirY > 0.25) {
          const ayMeas = (v.y - (vyPred - ayPred * dt)) / dt;
          const ayErr = ayMeas - ayPred;
          const gain = obs.t < 2.0 ? 0.08 : 0.015;
          KT = clamp(KT + gain * ayErr / (uT * avgDirY), 16.0, 27.5);
          estMass = clamp(15.2 / KT, 0.60, 0.85);
        }

        const AT = KT * uT;
        const axKnown = AT * avgDirX - cDrag * vx;
        const azKnown = AT * avgDirZ - cDrag * vz;

        const idx = stepCount & 3;
        const oldVx = histVx[idx], oldVz = histVz[idx];
        histVx[idx] = v.x; histVz[idx] = v.z;
        histAx[idx] = axKnown; histAz[idx] = azKnown;

        const vxPred = vx + (axKnown + wx) * dt;
        const pxPred = px + vxPred * dt;
        const epX = p.x - pxPred, evX = v.x - vxPred;
        px = pxPred + 0.65 * epX + 0.002 * evX;
        vx = vxPred + 8.0 * epX + 0.45 * evX;
        wx = clamp(wx + 22.0 * epX + 20.0 * evX, -4.5, 4.5);

        const vzPred = vz + (azKnown + wz) * dt;
        const pzPred = pz + vzPred * dt;
        const epZ = p.z - pzPred, evZ = v.z - vzPred;
        pz = pzPred + 0.65 * epZ + 0.002 * evZ;
        vz = vzPred + 8.0 * epZ + 0.45 * evZ;
        wz = clamp(wz + 22.0 * epZ + 20.0 * evZ, -4.5, 4.5);

        if (stepCount >= 8 && p.y > 0.10) {
          const sumAx = (histAx[0] + histAx[1] + histAx[2] + histAx[3]) * dt;
          const sumAz = (histAz[0] + histAz[1] + histAz[2] + histAz[3]) * dt;
          const wShortX = clamp((v.x - oldVx - sumAx) / (4 * dt), -4.5, 4.5);
          const wShortZ = clamp((v.z - oldVz - sumAz) / (4 * dt), -4.5, 4.5);
          if (Math.abs(wShortX - wx) > 0.55) wx = 0.45 * wx + 0.55 * wShortX;
          if (Math.abs(wShortZ - wz) > 0.55) wz = 0.45 * wz + 0.55 * wShortZ;
          if (obs.t >= 0.20 && obs.t < 1.98) {
            baseCount++;
            wBaseX += (wx - wBaseX) / baseCount;
            wBaseZ += (wz - wBaseZ) / baseCount;
          } else if (obs.t >= 2.0) {
            if (Math.abs(wShortX - wBaseX) < 0.35) wx += 0.25 * (wBaseX - wx);
            if (Math.abs(wShortZ - wBaseZ) < 0.35) wz += 0.25 * (wBaseZ - wz);
          }
        }

        refRoll += (lastRollDes - refRoll) * (dt / 0.085);
        refPitch += (lastPitchDes - refPitch) * (dt / 0.085);
        if (p.y > 0.10) {
          trimRoll = clamp(trimRoll + 2.2 * (att.roll - refRoll) * dt, -0.22, 0.22);
          trimPitch = clamp(trimPitch + 2.2 * (att.pitch - refPitch) * dt, -0.22, 0.22);
        }

        prevDirX = dirX; prevDirY = dirY; prevDirZ = dirZ;
      }
      stepCount++;

      let target, desVx = 0, desVy = 0, desVz = 0;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
          intX = 0; intZ = 0;
        }
        const dy = Math.abs(py - gate.y);
        const dz = Math.abs(pz - gate.z);
        const dtCross = clamp((gate.x - px) / Math.max(0.25, vx), 0, 0.35);
        const dyPred = Math.abs(py + vy * dtCross - gate.y);
        const dzPred = Math.abs(pz + vz * dtCross - gate.z);

        if (phase === 'align') {
          const alignX = gate.x - 0.38;
          target = { x: alignX, y: gate.y, z: gate.z };
          if (Math.abs(px - alignX) < 0.18 && dy < 0.09 && dz < 0.055 && Math.hypot(vy, vz) < 0.28) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle > 6) phase = 'cross';
        }
        if (phase === 'cross') {
          if (px < gate.x && px > gate.x - 0.32 && (dz > 0.068 || dy > 0.13 || dzPred > 0.075 || dyPred > 0.14)) {
            target = { x: Math.min(px - 0.04, gate.x - 0.18), y: gate.y, z: gate.z };
            desVx = 0;
          } else {
            target = { x: gate.x + 0.30, y: gate.y, z: gate.z };
            desVx = 0.55;
          }
        }
      } else {
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'pad_approach';
          intX = 0; intZ = 0;
        }
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - px, pad.z - pz);
        const speedXZ = Math.hypot(vx, vz);
        if (phase === 'pad_approach') {
          target = { x: pad.x, y: 0.45, z: pad.z };
          if (distXZ < 0.11 && speedXZ < 0.25 && py < 0.65) phase = 'descend';
        }
        if (phase === 'descend') {
          if (distXZ > 0.13) {
            target = { x: pad.x, y: Math.max(py, 0.20), z: pad.z };
          } else {
            target = { x: pad.x, y: 0.04, z: pad.z };
            desVy = py > 0.16 ? -0.35 : -0.12;
          }
        }
      }

      const ex = target.x - px;
      const ey = target.y - py;
      const ez = target.z - pz;

      if (Math.abs(ex) < 0.25) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(ez) < 0.25) intZ = clamp(intZ + ez * dt, -0.35, 0.35);
      intY = clamp(intY + ey * dt, -0.45, 0.45);

      const isGateCross = obs.gateIndex < 3 && phase === 'cross';
      const kpX = isGateCross ? 4.5 : 4.8;
      const kdX = isGateCross ? 3.8 : 3.9;
      const kpZ = obs.gateIndex < 3 ? 6.2 : 5.0;
      const kdZ = obs.gateIndex < 3 ? 4.4 : 4.0;

      const axFb = clamp(kpX * ex + kdX * (desVx - vx) + 1.5 * intX, -3.5, 3.5);
      const azFb = clamp(kpZ * ez + kdZ * (desVz - vz) + 2.2 * intZ, -3.8, 3.8);
      const ayFb = clamp(6.0 * ey + 4.2 * (desVy - vy) + 2.5 * intY, -3.5, 4.8);

      const cDrag = 0.42 / estMass;
      const Fx = axFb + cDrag * vx - wx;
      const Fy = Math.max(2.5, 9.81 + ayFb + cDrag * vy);
      const Fz = azFb + cDrag * vz - wz;
      const Fmag = Math.hypot(Fx, Fy, Fz);

      const FbodyX = cy * Fx - sy * Fz;
      const FbodyZ = sy * Fx + cy * Fz;

      const rollDes = clamp(-Math.asin(clamp(FbodyZ / Fmag, -0.55, 0.55)), -0.48, 0.48);
      const pitchDes = clamp(Math.atan2(FbodyX, Fy), -0.48, 0.48);

      const roll = clamp(rollDes - trimRoll + 0.30 * (rollDes - att.roll) - 0.035 * rates.roll, -0.55, 0.55);
      const pitch = clamp(pitchDes - trimPitch + 0.30 * (pitchDes - att.pitch) - 0.035 * rates.pitch, -0.55, 0.55);

      let thrust = Fy / (KT * Math.max(0.65, dirY));
      if (obs.gateIndex === 3 && phase === 'descend' && py <= 0.088 && Math.hypot(obs.pad.centre.x - px, obs.pad.centre.z - pz) <= 0.13 && Math.hypot(vx, vy, vz) < 0.38) {
        thrust = 0;
        lastRollDes = 0;
        lastPitchDes = 0;
        lastThrust = 0;
        return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
      }
      thrust = clamp(thrust, 0.05, 1.0);

      if (p.y > 0.10) intYaw = clamp(intYaw + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.2 * att.yaw - 0.25 * rates.yaw - 3.5 * intYaw, -2.0, 2.0);

      lastThrust = thrust;
      lastRollDes = rollDes;
      lastPitchDes = pitchDes;

      return { thrust, roll, pitch, yawRate };
    },
  };
}

